preprocessing.cypher_query:
MATCH (n:IntAct_Experiment)
WHERE n.secondary_xref IS NOT NULL AND n.imex_id IS NULL
SET n.imex_id = [xref IN n.secondary_xref WHERE xref STARTS WITH 'imex:'][0];

MATCH (n:RefSeq_MobileGeneticElement)
WHERE n.id IS NOT NULL
SET n.mge_id = replace(n.id, 'id-GeneID:', '');
